use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 428. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static BYBIT: &[SettingDef] = &[
    d("Площадки", "venue.book_backup_levels", K::Choice, L::None, "уровней", V, "Решение 428, только Bybit: страховка стакана — на каждое соединение стаканов ещё одно соединение (backup-N) с теми же парами и другой глубиной orderbook.{1|50|200|1000}.{SYM} (официально «Supports different depths»; спот: 1 — 10 мс и только снимки, 50 — 20 мс, 200 — 100 мс, 1000 — 200 мс). Пока основной поток (venue.depth_levels) синхронизирован — ядру идёт он; разрыв номера u, обрыв соединения или отказ подписки — сразу последний стакан страховки (если он моложе venue.book_stale_ms и новее отданного по seq), основной пересподписывается за снимком и после снимка снова основной. Ядру — не больше venue.depth_levels уровней: при глубине 1 у страховки — только лучший уровень. Должна отличаться от venue.depth_levels. Соединений вдвое больше (лимит Bybit — 500 подключений за 5 минут на домен). Смена глубины — со следующей подпиской; снять — соединения страховки останавливаются. Не задана — страховки нет, как раньше (журнал venue.book_backup — переключения и сверки)").choices(&["1", "50", "200", "1000"]).optional(),
];
